INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_032_M2_S1', 'rain gauges', '1', 'rain gauges: Instruments used to measure precipitation depth over a specified period. In Hydrologic Measurement and Data Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of rain gauges within Water Resources Engineering, particularly where the Hydrologic Measurement and Data Analysis module establishes its technical context.', 'SSD_COURSE_032_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M2_S2', 'stream gauging', '2', 'stream gauging: Measurement of river stage and discharge to establish the flow behaviour of a stream. In Hydrologic Measurement and Data Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of stream gauging within Water Resources Engineering, particularly where the Hydrologic Measurement and Data Analysis module establishes its technical context.', 'SSD_COURSE_032_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M2_S3', 'hydrographs', '3', 'hydrographs: Graphs showing streamflow or another hydrological variable as a function of time. In Hydrologic Measurement and Data Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of hydrographs within Water Resources Engineering, particularly where the Hydrologic Measurement and Data Analysis module establishes its technical context.', 'SSD_COURSE_032_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M2_S4', 'frequency analysis', '4', 'frequency analysis: Statistical analysis of hydrologic observations to estimate the frequency or probability of events such as floods or extreme rainfall. In Hydrologic Measurement and Data Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of frequency analysis within Water Resources Engineering, particularly where the Hydrologic Measurement and Data Analysis module establishes its technical context.', 'SSD_COURSE_032_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M2_S5', 'data consistency', '5', 'data consistency: Checks that identify errors, shifts, or inconsistencies in hydrological records before analysis. In Hydrologic Measurement and Data Analysis, the focus is on the analysis, design, implementation, interpretation, or evaluation of data consistency within Water Resources Engineering, particularly where the Hydrologic Measurement and Data Analysis module establishes its technical context.', 'SSD_COURSE_032_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M3_S1', 'unit hydrograph', '1', 'unit hydrograph refers to the runoff hydrograph produced by a unit depth of effective rainfall over a specified watershed and duration. In Hydrologic Modelling and Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of unit hydrograph within Water Resources Engineering, particularly where the Hydrologic Modelling and Design module establishes its technical context.', 'SSD_COURSE_032_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M3_S2', 'rainfall-runoff models', '2', 'rainfall-runoff models: Models that estimate watershed runoff from rainfall and other catchment characteristics. In Hydrologic Modelling and Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of rainfall-runoff models within Water Resources Engineering, particularly where the Hydrologic Modelling and Design module establishes its technical context.', 'SSD_COURSE_032_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M3_S3', 'flood estimation', '3', 'flood estimation: Determining design flood magnitudes or frequencies from hydrological data and models. In Hydrologic Modelling and Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of flood estimation within Water Resources Engineering, particularly where the Hydrologic Modelling and Design module establishes its technical context.', 'SSD_COURSE_032_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M3_S4', 'design storms', '4', 'design storms: Design rainfall or storm events selected using statistical frequency analysis and specified return-period or risk criteria for hydraulic and water-resources design. In Hydrologic Modelling and Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of design storms within Water Resources Engineering, particularly where the Hydrologic Modelling and Design module establishes its technical context.', 'SSD_COURSE_032_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M4_S1', 'storage-yield analysis', '1', 'storage-yield analysis: Analysis of the relationship between reservoir storage, inflow variability, operating policy, and the yield that can be supplied at a specified reliability. In Reservoirs and Water Storage, the focus is on the analysis, design, implementation, interpretation, or evaluation of storage-yield analysis within Water Resources Engineering, particularly where the Reservoirs and Water Storage module establishes its technical context.', 'SSD_COURSE_032_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M4_S2', 'reservoir routing', '2', 'reservoir routing: Calculation of how reservoir storage, inflow, and outflow change during a flood or operating event. In Reservoirs and Water Storage, the focus is on the analysis, design, implementation, interpretation, or evaluation of reservoir routing within Water Resources Engineering, particularly where the Reservoirs and Water Storage module establishes its technical context.', 'SSD_COURSE_032_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M4_S3', 'sedimentation', '3', 'sedimentation: Accumulation of transported sediment in reservoirs, channels, or other water infrastructure. In Reservoirs and Water Storage, the focus is on the analysis, design, implementation, interpretation, or evaluation of sedimentation within Water Resources Engineering, particularly where the Reservoirs and Water Storage module establishes its technical context.', 'SSD_COURSE_032_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M4_S4', 'operating rules', '4', 'operating rules: Specified rules for releasing or storing water from reservoirs and other controlled water systems. In Reservoirs and Water Storage, the focus is on the analysis, design, implementation, interpretation, or evaluation of operating rules within Water Resources Engineering, particularly where the Reservoirs and Water Storage module establishes its technical context.', 'SSD_COURSE_032_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M5_S1', 'aquifers', '1', 'aquifers: Permeable geological formations that store and transmit groundwater. In Groundwater Resources, the focus is on the analysis, design, implementation, interpretation, or evaluation of aquifers within Water Resources Engineering, particularly where the Groundwater Resources module establishes its technical context.', 'SSD_COURSE_032_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M5_S2', 'Darcy law', '2', 'Darcy law: Analysis of groundwater flow to and from wells, including drawdown and pumping response. In Groundwater Resources, the focus is on the analysis, design, implementation, interpretation, or evaluation of well hydraulics within Water Resources Engineering, particularly where the Groundwater Resources module establishes its technical context.', 'SSD_COURSE_032_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M5_S3', 'well hydraulics', '3', 'well hydraulics: Analysis of groundwater flow to and from wells, including drawdown and pumping response. In Groundwater Resources, the focus is on the analysis, design, implementation, interpretation, or evaluation of well hydraulics within Water Resources Engineering, particularly where the Groundwater Resources module establishes its technical context.', 'SSD_COURSE_032_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M5_S4', 'recharge', '4', 'recharge: Addition of water to an aquifer, commonly from infiltration or surface-water sources. In Groundwater Resources, the focus is on the analysis, design, implementation, interpretation, or evaluation of recharge within Water Resources Engineering, particularly where the Groundwater Resources module establishes its technical context.', 'SSD_COURSE_032_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M5_S5', 'groundwater modelling', '5', 'groundwater modelling: Mathematical or numerical representation of groundwater flow and, where included, solute transport to analyse aquifer behaviour and management scenarios. In Groundwater Resources, the focus is on the analysis, design, implementation, interpretation, or evaluation of groundwater modelling within Water Resources Engineering, particularly where the Groundwater Resources module establishes its technical context.', 'SSD_COURSE_032_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M6_S1', 'allocation', '1', 'allocation: Distribution of available water among users, ecosystems, and competing demands subject to constraints. In Water Resources Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of allocation within Water Resources Engineering, particularly where the Water Resources Systems module establishes its technical context.', 'SSD_COURSE_032_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M6_S2', 'demand forecasting', '2', 'demand forecasting: Estimation of future demand for a resource or service from historical observations, explanatory variables, assumptions, and uncertainty, used to support planning and design. In Water Resources Systems, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_032_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M6_S3', 'systems analysis', '3', 'systems analysis: Evaluation of interacting water-resources components, demands, constraints, and operating policies to compare system performance and alternatives. In Water Resources Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of systems analysis within Water Resources Engineering, particularly where the Water Resources Systems module establishes its technical context.', 'SSD_COURSE_032_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M6_S4', 'optimization', '4', 'optimization: Selection of decision variables or operating conditions to maximize or minimize an objective subject to specified constraints; the objective and constraints depend on the application domain. In Water Resources Systems, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_032_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M6_S5', 'conjunctive use', '5', 'conjunctive use: Coordinated management of surface water and groundwater as interconnected resources. In Water Resources Systems, the focus is on the analysis, design, implementation, interpretation, or evaluation of conjunctive use within Water Resources Engineering, particularly where the Water Resources Systems module establishes its technical context.', 'SSD_COURSE_032_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M7_S1', 'flood routing', '1', 'flood routing: Computation of how a flood wave changes as it moves through a river reach or reservoir. In Flood and Drought Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of flood routing within Water Resources Engineering, particularly where the Flood and Drought Management module establishes its technical context.', 'SSD_COURSE_032_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M7_S2', 'floodplain management', '2', 'floodplain management: Planning and regulation of flood-prone land to reduce risk while accounting for river functions. In Flood and Drought Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of floodplain management within Water Resources Engineering, particularly where the Flood and Drought Management module establishes its technical context.', 'SSD_COURSE_032_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M7_S3', 'drought indices', '3', 'drought indices: Numerical indicators used to quantify the severity, duration, or spatial extent of drought. In Flood and Drought Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of drought indices within Water Resources Engineering, particularly where the Flood and Drought Management module establishes its technical context.', 'SSD_COURSE_032_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M7_S4', 'early warning', '4', 'early warning: Systems that detect developing hazards and communicate timely information for preparedness and response. In Flood and Drought Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of early warning within Water Resources Engineering, particularly where the Flood and Drought Management module establishes its technical context.', 'SSD_COURSE_032_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_032_M7_S5', 'risk analysis', '5', 'risk analysis: Systematic estimation of the likelihood and consequences of uncertain hazards or failures to support water-resources planning and decisions. In Flood and Drought Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of risk analysis within Water Resources Engineering, particularly where the Flood and Drought Management module establishes its technical context.', 'SSD_COURSE_032_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M1_S1', 'pressure', '1', 'pressure: Normal force per unit area acting on a surface or within a fluid; in continuum fluid mechanics it is a scalar state variable whose spatial gradients can drive flow. In Fluid Properties and Fundamental Flow, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_033_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M1_S2', 'viscosity', '2', 'viscosity refers to a measure of a fluid’s resistance to deformation and flow, arising from internal friction and relating shear stress to velocity gradient under Newtonian conditions. In Fluid Properties and Fundamental Flow, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_033_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M1_S3', 'hydrostatics', '3', 'hydrostatics: Analysis of fluids at rest, including pressure distributions, forces on submerged surfaces, buoyancy, and related equilibrium conditions. In Fluid Properties and Fundamental Flow, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_033_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M1_S4', 'Bernoulli equation', '4', 'Bernoulli equation refers to an energy equation relating pressure head, velocity head, elevation head, and losses along a streamline under stated assumptions. In Fluid Properties and Fundamental Flow, the focus is on the analysis, design, implementation, interpretation, or evaluation of Bernoulli equation within Hydraulics and Hydraulic Engineering, particularly where the Fluid Properties and Fundamental Flow module establishes its technical context.', 'SSD_COURSE_033_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M1_S5', 'control volumes', '5', 'control volumes refers to a defined region in space used for applying conservation equations to mass, momentum, and energy crossing its boundary. In Fluid Properties and Fundamental Flow, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_033_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M2_S1', 'laminar flow', '1', 'laminar flow: Flow regime characterized by relatively ordered fluid motion with limited cross-stream mixing and viscous forces dominating over inertial effects at sufficiently low Reynolds number. In Pipe Flow, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_033_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M2_S2', 'turbulent flow', '2', 'turbulent flow: Flow regime characterized by irregular, three-dimensional fluctuations and enhanced mixing, typically associated with sufficiently high Reynolds number and strong inertial effects. In Pipe Flow, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_033_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M2_S3', 'Darcy-Weisbach', '3', 'Darcy-Weisbach refers to an equation for head loss due to friction in pressurised pipe flow. In Pipe Flow, the focus is on the analysis, design, implementation, interpretation, or evaluation of Darcy-Weisbach within Hydraulics and Hydraulic Engineering, particularly where the Pipe Flow module establishes its technical context.', 'SSD_COURSE_033_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M2_S4', 'minor losses', '4', 'minor losses: Local hydraulic losses caused by fittings, entrances, exits, bends, valves, and other disturbances. In Pipe Flow, the focus is on the analysis, design, implementation, interpretation, or evaluation of minor losses within Hydraulics and Hydraulic Engineering, particularly where the Pipe Flow module establishes its technical context.', 'SSD_COURSE_033_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M2_S5', 'pipe networks', '5', 'pipe networks: Connected systems of pipes in which flow rates and pressures must satisfy continuity and energy relationships. In Pipe Flow, the focus is on the analysis, design, implementation, interpretation, or evaluation of pipe networks within Hydraulics and Hydraulic Engineering, particularly where the Pipe Flow module establishes its technical context.', 'SSD_COURSE_033_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M3_S1', 'specific energy', '1', 'specific energy: Flow energy measured relative to the channel bed, used particularly in open-channel critical-flow analysis. In Open Channel Flow, the focus is on the analysis, design, implementation, interpretation, or evaluation of specific energy within Hydraulics and Hydraulic Engineering, particularly where the Open Channel Flow module establishes its technical context.', 'SSD_COURSE_033_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M3_S2', 'critical flow', '2', 'critical flow refers to an open-channel condition at which specific energy is minimum for a given discharge. In Open Channel Flow, the focus is on the analysis, design, implementation, interpretation, or evaluation of critical flow within Hydraulics and Hydraulic Engineering, particularly where the Open Channel Flow module establishes its technical context.', 'SSD_COURSE_033_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M3_S3', 'uniform flow', '3', 'uniform flow: Open-channel flow with constant depth and velocity along the channel under uniform conditions. In Open Channel Flow, the focus is on the analysis, design, implementation, interpretation, or evaluation of uniform flow within Hydraulics and Hydraulic Engineering, particularly where the Open Channel Flow module establishes its technical context.', 'SSD_COURSE_033_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M3_S4', 'gradually varied flow', '4', 'gradually varied flow: Open-channel flow whose depth changes gradually along the channel. In Open Channel Flow, the focus is on the analysis, design, implementation, interpretation, or evaluation of gradually varied flow within Hydraulics and Hydraulic Engineering, particularly where the Open Channel Flow module establishes its technical context.', 'SSD_COURSE_033_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M3_S5', 'hydraulic jumps', '5', 'hydraulic jumps: Rapid transitions from supercritical to subcritical flow accompanied by energy dissipation. In Open Channel Flow, the focus is on the analysis, design, implementation, interpretation, or evaluation of hydraulic jumps within Hydraulics and Hydraulic Engineering, particularly where the Open Channel Flow module establishes its technical context.', 'SSD_COURSE_033_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M4_S1', 'centrifugal pumps', '1', 'centrifugal pumps: Rotodynamic pumps that impart energy to a fluid primarily through the action of a rotating impeller, converting mechanical energy into fluid pressure and head. In Hydraulic Machines, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_033_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M4_S2', 'reciprocating pumps', '2', 'reciprocating pumps: Positive-displacement pumps that move fluid using the cyclic motion of pistons or plungers. In Hydraulic Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of reciprocating pumps within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic Machines module establishes its technical context.', 'SSD_COURSE_033_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M4_S3', 'turbines', '3', 'turbines: Hydraulic machines that convert water energy into mechanical shaft power. In Hydraulic Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of turbines within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic Machines module establishes its technical context.', 'SSD_COURSE_033_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M4_S4', 'cavitation', '4', 'cavitation: Formation and collapse of vapour cavities when local pressure falls below the fluid''s vapour pressure. In Hydraulic Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of cavitation within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic Machines module establishes its technical context.', 'SSD_COURSE_033_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M4_S5', 'performance curves', '5', 'performance curves: Graphs relating hydraulic-machine variables such as head, flow, efficiency, and power. In Hydraulic Machines, the focus is on the analysis, design, implementation, interpretation, or evaluation of performance curves within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic Machines module establishes its technical context.', 'SSD_COURSE_033_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M5_S1', 'weirs', '1', 'weirs: Overflow structures used to control or measure open-channel flow. In Hydraulic Structures, the focus is on the analysis, design, implementation, interpretation, or evaluation of weirs within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic Structures module establishes its technical context.', 'SSD_COURSE_033_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_033_M5_S2', 'spillways', '2', 'spillways: Structures that safely convey excess reservoir water downstream. In Hydraulic Structures, the focus is on the analysis, design, implementation, interpretation, or evaluation of spillways within Hydraulics and Hydraulic Engineering, particularly where the Hydraulic Structures module establishes its technical context.', 'SSD_COURSE_033_M5_S2', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;